import { getSupabaseServiceRoleClient } from "@/lib/services/supabase/server";
import { executeQuery } from "./query";
import { hash } from "bcrypt";
import { User } from "./types/database";

// Type for user creation/update, omitting fields generated by the database.
export type UserInput = Omit<Partial<User>, 'id' | 'created_at' | 'updated_at'>;

export const UserDAO = {
  async getAll(): Promise<User[]> {
    const supabase = await getSupabaseServiceRoleClient();
    const query = supabase
      .from("users")
      .select(`
        id,
        email,
        name,
        avatar_url,
        is_active,
        role_id,
        role:roles(id, name),
        created_at
      `)
      .order("created_at", { ascending: false });
    
    // The return type from the query will be slightly different due to the join
    return executeQuery(query) as unknown as User[];
  },

  async create(userData: UserInput): Promise<User[]> {
    const supabase = await getSupabaseServiceRoleClient();
    const { password, ...rest } = userData;
    if (!password) throw new Error("Password is required for new users.");
    
    const hashedPassword = await hash(password, 12);
    const query = supabase.from("users").insert([{ ...rest, hashed_password: hashedPassword }]);
    return executeQuery(query);
  },

  async update(userId: string, userData: UserInput): Promise<User[]> {
    const supabase = await getSupabaseServiceRoleClient();
    const { password, ...rest } = userData;

    if (password) {
      const hashedPassword = await hash(password, 12);
      const query = supabase.from("users").update({ ...rest, hashed_password: hashedPassword }).eq("id", userId);
      return executeQuery(query);
    } else {
      const query = supabase.from("users").update(rest).eq("id", userId);
      return executeQuery(query);
    }
  },

  async delete(userId: string): Promise<User[]> {
    const supabase = await getSupabaseServiceRoleClient();
    const query = supabase.from("users").delete().eq("id", userId);
    return executeQuery(query);
  },

  async updateStatus(userId: string, isActive: boolean): Promise<User[]> {
    const supabase = await getSupabaseServiceRoleClient();
    const query = supabase.from("users").update({ is_active: isActive, updated_at: new Date().toISOString() }).eq("id", userId);
    return executeQuery(query);
  },

  async updateRole(userId: string, roleId: string | null): Promise<User[]> {
    const supabase = await getSupabaseServiceRoleClient();
    const updateData = { role_id: roleId };
    const query = supabase.from("users").update({ ...updateData, updated_at: new Date().toISOString() }).eq("id", userId);
    return executeQuery(query);
  },

  async updatePassword(userId: string, newPassword: string): Promise<User[]> {
    const supabase = await getSupabaseServiceRoleClient();
    const hashedPassword = await hash(newPassword, 12);
    const query = supabase.from("users").update({ hashed_password: hashedPassword, updated_at: new Date().toISOString() }).eq("id", userId);
    return executeQuery(query);
  }
};

  export async function getUserById(userId: string): Promise<User | null> {
    const supabase = await getSupabaseServiceRoleClient()
    const { data, error } = await supabase
      .from('users')
      .select('*')
      .eq('id', userId)
      .single()

    if (error) {
      console.error('Error fetching user by ID:', error)
      return null
    }
    return data as User
  }

  export async function getUserByEmail(email: string): Promise<User | null> {
    const supabase = await getSupabaseServiceRoleClient()
    const { data, error } = await supabase
      .from('users')
      .select('*')
      .eq('email', email)
      .single()

    if (error) {
      console.error('Error fetching user by email:', error)
      return null
    }
    return data as User
  }